// 인원모집 › 답장: SMS Gateway(사장님 폰)가 받은 문자를 POST sms-in-… (sms:received). 모집 중에 물어본 번호의 답만 본다 —
// 다른 문자(가족·업체)는 그냥 지나간다. 네 → 텔레그램 [넣기][안 넣기], 아니요 → '아쉽네요' + 다음 사람, 애매 → 원문 + 버튼
const body = $('답장받음').first().json.body || {};
const pl = body.payload || body;
